import {playFloorSound} from './floor-sound.js';
import {createMenuMusic} from './menu-music.js';
import {W,H,LOOT,CAPACITY,newRun,stats,update,distance,sight,interact,dropLoot,nextFloor} from './engine.js?v=unpredictable-7';
const $=id=>document.getElementById(id),canvas=$('game'),ctx=canvas.getContext('2d');let state=newRun(32917),started=false,mode='random',seed=0,last=0,muted=false,audio=null,toastUntil=0,particles=[],floating=[],best=0,bestFloor=0,pausedForHelp=false;const keys={},touch={};
try{const saved=JSON.parse(localStorage.getItem('one-more-floor-best')||'{}');best=Number(saved.score)||0;bestFloor=Number(saved.floor)||0;}catch{}
const menuMusic=createMenuMusic(new Audio('./audio/spy-showdown.mp3'),()=>toast('Music could not start. Tap sound OFF, then ON to retry.'));
let audioUnlocked=false;
function syncMenuMusic(){menuMusic.sync({menu:state.mode==='intro'&&audioUnlocked,muted,hidden:document.hidden});}
function unlockAudio(){audioUnlocked=true;syncMenuMusic();}
document.addEventListener('pointerdown',unlockAudio,{once:true});
document.addEventListener('keydown',unlockAudio,{once:true});
document.addEventListener('visibilitychange',syncMenuMusic);
function tone(freq=440,duration=.1,type='sine',volume=.045){if(muted)return;try{audio??=new(window.AudioContext||window.webkitAudioContext)();audio.resume();const o=audio.createOscillator(),g=audio.createGain();o.type=type;o.frequency.setValueAtTime(freq,audio.currentTime);g.gain.setValueAtTime(volume,audio.currentTime);g.gain.exponentialRampToValueAtTime(.001,audio.currentTime+duration);o.connect(g);g.connect(audio.destination);o.start();o.stop(audio.currentTime+duration);}catch{}}
// Capture clicks before modal handlers replace their buttons. Keyboard activation
// also emits click; held movement controls get one cue on pointerdown instead.
function clickSound(){
  if(muted||document.hidden)return;
  try{
    audio??=new(window.AudioContext||window.webkitAudioContext)();
    audio.resume().catch(()=>{});
    const t=audio.currentTime,o=audio.createOscillator(),g=audio.createGain();
    o.type='triangle';o.frequency.setValueAtTime(880,t);
    o.frequency.exponentialRampToValueAtTime(440,t+.07);
    g.gain.setValueAtTime(0,t);g.gain.linearRampToValueAtTime(.07,t+.004);
    g.gain.exponentialRampToValueAtTime(.0001,t+.09);
    o.connect(g);g.connect(audio.destination);
    o.onended=()=>{o.disconnect();g.disconnect();};
    o.start(t);o.stop(t+.1);
  }catch{}
}
document.addEventListener('click',e=>{
  const button=e.target.closest?.('button');
  if(!button||button.disabled||button.id==='sound')return;
  if(button.matches('[data-dir],#sneak')&&e.detail>0)return;
  clickSound();
},true);
let stopFloorSound=()=>{};
function floorSound(advancing=false){stopFloorSound();if(muted||document.hidden)return;try{audio??=new(window.AudioContext||window.webkitAudioContext)();audio.resume();stopFloorSound=playFloorSound(audio,advancing);}catch{}}
document.addEventListener('visibilitychange',()=>{if(document.hidden)stopFloorSound();});
function toast(t){$('toast').textContent=t;$('toast').classList.add('show');toastUntil=performance.now()+2400;}
function modal(html){$('overlay').innerHTML=`<div class="modal">${html}</div>`;$('overlay').classList.remove('hidden');keysClear();const b=$('overlay').querySelector('button');b?.focus({preventScroll:true});}
function hideModal(){$('overlay').classList.add('hidden');canvas.focus({preventScroll:true});}
function keysClear(){Object.keys(keys).forEach(k=>keys[k]=false);Object.keys(touch).forEach(k=>touch[k]=false);}
function intro(){state.mode='intro';syncMenuMusic();modal(`<span class="badge">WELCOME TO THE GILDED TOWER</span><h2>TAKE THE LOOT.<br>KNOW WHEN TO LEAVE.</h2><p>Gold weighs you down. Diamonds give you away.<br>Coins make a racket. Getting caught costs it all.</p><button class="primary" id="start">LET’S GET GREEDY</button><button class="secondary" id="daily">PLAY TODAY’S TOWER</button><p class="micro">GRAB LOOT · DODGE GUARDS · ESCAPE OR CLIMB</p>`);$('start').onclick=()=>start('random');$('daily').onclick=()=>start('daily');}
function start(m){mode=m;seed=m==='daily'?Number(new Date().toISOString().slice(0,10).replaceAll('-','')):Math.floor(Math.random()*1e8);state=newRun(seed);syncMenuMusic();started=true;particles=[];floating=[];hideModal();tone(300,.15);toast('Collect treasure. Green hatch = escape. Purple stairs = climb.');hud();}
function result(won){keysClear();let record=false;if(won&&state.score>best){record=true;best=state.score;bestFloor=state.floor;try{localStorage.setItem('one-more-floor-best',JSON.stringify({score:best,floor:bestFloor}));}catch{}}
tone(won?660:120,.4,won?'sine':'sawtooth');modal(`<span class="badge">${won?(record?'A NEW PERSONAL BEST':'A CLEAN GETAWAY'):'GREED GOT THE BETTER OF YOU'}</span><h2>${won?'YOU GOT AWAY.':'BUSTED.'}</h2><div class="result-value">◆ ${won?state.score.toLocaleString():0}</div><p>${won?`Banked safely from floor ${state.floor}.<br>${state.score?'A fine haul. But what was upstairs?':'An empty bag. An excellent survival instinct.'}`:`${state.score.toLocaleString()} in treasure left behind on floor ${state.floor}.<br>${state.reason||'Stay out of the light and sneak past patrols.'}`}</p><button class="primary" id="again">${mode==='daily'?'RETRY TODAY’S TOWER':'ONE MORE GO'}</button><button class="secondary" id="menu">Back to the lobby</button><p class="micro">${mode==='daily'?'DAILY TOWER · '+new Date().toISOString().slice(0,10):'YOUR BEST ESCAPE: '+best.toLocaleString()}</p>`);$('again').onclick=()=>start(mode);$('menu').onclick=intro;hud();}
function action(){if(!started||state.mode!=='playing')return;const r=interact(state);if(r==='escaped')result(true);else if(r==='stairs'){floorSound();modal(`<span class="badge">FLOOR ${String(state.floor).padStart(2,'0')} → ${String(state.floor+1).padStart(2,'0')}</span><h2>FEELING<br>A LITTLE GREEDY?</h2><p>You’re carrying <b>${state.score.toLocaleString()}</b>.<br>The next floor has richer loot and tougher patrols.<br>Your whole bag is still on the line.</p><button class="primary" id="climb">ONE MORE FLOOR &nbsp; ↑</button><button class="secondary" id="stay">Stay here and find the green escape hatch</button><p class="micro">CLIMBING DOES NOT BANK YOUR TREASURE</p>`);$('climb').onclick=()=>{floorSound(true);nextFloor(state);hideModal();toast(state.floor>=5?'Floor '+state.floor+'. Guards now change patrol routes. Stay alert.':'Floor '+state.floor+'. Richer loot. Same bad decisions.');hud();};$('stay').onclick=()=>{stopFloorSound();state.mode='playing';hideModal();};}else toast('Get closer to the green hatch or purple stairs.');}
function pause(){if(!started||!['playing','paused'].includes(state.mode))return;if(state.mode==='paused'){state.mode='playing';hideModal();return;}state.mode='paused';modal(`<span class="badge">YOUR HAUL IS ON HOLD</span><h2>CATCH YOUR BREATH.</h2><p>The guards can wait. Your treasure is right here.</p><button class="primary" id="resume">BACK TO THE HEIST</button><button class="secondary" id="abandon">Abandon run</button>`);$('resume').onclick=pause;$('abandon').onclick=intro;}
function help(){if(state.mode==='stairs'||state.mode==='caught'||state.mode==='escaped')return;pausedForHelp=started&&state.mode==='playing';if(pausedForHelp)state.mode='paused';modal(`<span class="badge">A THIEF’S FIELD GUIDE</span><h2>GET RICH.<br>GET OUT.</h2><ul><li>Walk over loot to collect it. Your bag holds 12 items.</li><li>Stay outside the guards’ gold vision cones. Red means you’re being spotted!</li><li>Hold <b>Space / SNEAK</b> to move quietly. Diamonds still glow.</li><li>Press <b>Q / Drop</b> to leave your last treasure behind.</li><li>Pulsing red floor plates are dangerous. Cross when dark.</li><li>At the <b>green hatch</b>, press E to bank everything.</li><li>At the <b>purple stairs</b>, press E to climb. No banking!</li></ul><button class="primary" id="close-help">GOT IT. LET’S GO.</button>`);$('close-help').onclick=()=>{if(pausedForHelp){state.mode='playing';hideModal();}else intro();};}
$('sound').onclick=()=>{muted=!muted;if(muted)stopFloorSound();$('sound').innerHTML='♪ <span>'+(muted?'OFF':'ON')+'</span>';$('sound').setAttribute('aria-label',muted?'Enable sound':'Mute sound');clickSound();syncMenuMusic();};$('pause').onclick=pause;$('help').onclick=help;$('interact').onclick=action;$('drop').onclick=()=>{if(dropLoot(state)){tone(190,.1);hud();}else if(state.mode==='playing')toast('Your bag is empty. A suspiciously honest thief.');};
window.addEventListener('keydown',e=>{if(['ArrowUp','ArrowDown','ArrowLeft','ArrowRight',' '].includes(e.key)&&started)e.preventDefault();keys[e.key.toLowerCase()]=true;if(e.repeat)return;if(e.key.toLowerCase()==='e')action();if(e.key.toLowerCase()==='q')$('drop').click();if(e.key.toLowerCase()==='p'||e.key==='Escape')pause();});window.addEventListener('keyup',e=>keys[e.key.toLowerCase()]=false);window.addEventListener('blur',()=>{keysClear();if(state.mode==='playing')pause();});document.addEventListener('visibilitychange',()=>{if(document.hidden){keysClear();if(state.mode==='playing')pause();}});
for(const b of document.querySelectorAll('[data-dir],#sneak')){const k=b.dataset.dir||'sneak';b.addEventListener('pointerdown',e=>{e.preventDefault();clickSound();touch[k]=true;b.setPointerCapture(e.pointerId);});for(const ev of ['pointerup','pointercancel','lostpointercapture'])b.addEventListener(ev,()=>touch[k]=false);b.addEventListener('contextmenu',e=>e.preventDefault());}
function hud(){const s=stats(state.bag);$('floor').textContent=String(state.floor).padStart(2,'0');$('score').textContent=state.score.toLocaleString();$('bag-count').textContent=state.bag.length+' / '+CAPACITY;for(const t of ['gold','diamond','coin'])$(t+'-count').textContent=s[t];$('speed-label').textContent=Math.round(s.speed*100)+'%';$('speed-meter').style.width=s.speed*100+'%';$('effect-note').textContent=state.bag.length===CAPACITY?'Bag full. Drop something to pick up more.':s.diamond&&s.coin?'You glow. You jingle. Sneak carefully.':s.diamond?'Diamonds extend the guards’ vision.':s.coin?'Hold sneak to silence your coin purses.':s.gold?'Gold is slowing your getaway.':'Travel light. For now.';$('best').textContent=best.toLocaleString();$('best-floor').textContent=bestFloor?'Banked from floor '+bestFloor:'A clean getaway is priceless.';}
// All artwork is drawn here: no third-party sprites or character assets.
