function person(x,y,color,angle=0,player=false,time=0){ctx.save();ctx.translate(x,y);ctx.fillStyle='#0004';ctx.beginPath();ctx.ellipse(0,15,15,6,0,0,7);ctx.fill();const bob=player?Math.sin(time)*1.4:0;ctx.translate(0,bob);if(player){fillRound(6,-2,12,18,'#a18d61',5);fillRound(-9,6,7,11,'#24252c',3);fillRound(3,6,7,11,'#24252c',3);}else{fillRound(-9,6,7,11,'#25282c',3);fillRound(3,6,7,11,'#25282c',3);}fillRound(-12,-9,24,23,color,7);ctx.fillStyle=player?'#b29bd3':'#879386';ctx.beginPath();ctx.arc(0,-12,12,0,Math.PI*2);ctx.fill();if(player){fillRound(-10,-15,20,9,'#30313a',3);fillRound(-5,-12,3,3,'#fbf2d6',1);fillRound(3,-12,3,3,'#fbf2d6',1);ctx.fillStyle='#9271b5';ctx.beginPath();ctx.moveTo(-11,-17);ctx.lineTo(-4,-32);ctx.lineTo(10,-18);ctx.closePath();ctx.fill();line(-9,-19,7,-19,'#c7b2e1',2);}else{fillRound(-13,-22,26,8,'#667967',3);fillRound(-4,-20,8,4,'#c9b676',1);const dx=Math.cos(angle)*7;fillRound(dx-5,-13,10,5,'#282e30',2);ctx.fillStyle='#eccf80';ctx.beginPath();ctx.arc(Math.cos(angle)*19,Math.sin(angle)*13,4,0,7);ctx.fill();}ctx.restore();}
function render(time){const {room,player}=state;ctx.clearRect(0,0,W,H);ctx.fillStyle='#302f33';ctx.fillRect(0,0,W,H);fillRound(30,28,840,563,'#ada594',12);fillRound(38,38,824,544,'#d6cdb8',3);
for(let y=40;y<580;y+=38){for(let x=40;x<860;x+=38){const n=((x*13+y*7)%17)/17;ctx.fillStyle=n>.6?'#c8bea82a':'#f5ecd21a';ctx.fillRect(x+1,y+1,36,36);}}ctx.strokeStyle='#b8ac931f';ctx.lineWidth=1;for(let x=40;x<860;x+=38)line(x,40,x,580,'#a99d8722');for(let y=40;y<580;y+=38)line(40,y,860,y,'#a99d8722');
// Rugs and tiny architectural details.
for(const [x,y,w,h] of [[80,105,160,330],[355,70,190,320],[660,290,170,240]]){fillRound(x,y,w,h,'#b8a58c28',4);ctx.strokeStyle='#baaa902e';ctx.lineWidth=2;ctx.strokeRect(x+9,y+9,w-18,h-18);}text('01 / SERVICE',170,563,8,'#9b907b');text('02 / COLLECTION',450,563,8,'#9b907b');text('03 / UPPER VAULT',750,563,8,'#9b907b');
// Escape hatch.
const e=room.exit;ctx.save();ctx.translate(e.x,e.y);ctx.shadowBlur=24;ctx.shadowColor='#91bb8270';fillRound(-27,-25,54,50,'#617e68',6);ctx.shadowBlur=0;ctx.strokeStyle='#c3d3a4';ctx.lineWidth=2;round(-21,-19,42,38,3);ctx.stroke();text('↙',0,9,30,'#ecf1c9');text('ESCAPE',0,42,10,'#60765a');ctx.restore();
const a=room.stairs;fillRound(a.x-27,a.y-27,54,54,'#8c77aa',5);for(let i=0;i<4;i++){fillRound(a.x-18+i*4,a.y+14-i*10,36-i*5,6,'#d1c0e4',1);}text('CLIMB ↑',a.x,a.y+43,10,'#827196');
for(const t of room.traps){fillRound(t.x-23,t.y-23,46,46,t.active?'#a35f55':'#aa9d86',4);for(let j=0;j<3;j++)for(let i=0;i<3;i++){ctx.fillStyle=t.active?'#f7d6a2':'#80745f';ctx.beginPath();ctx.moveTo(t.x-15+i*12,t.y-10+j*12);ctx.lineTo(t.x-10+i*12,t.y+(t.active?-22:-15)+j*12);ctx.lineTo(t.x-5+i*12,t.y-10+j*12);ctx.fill();}if(!t.active){ctx.strokeStyle='#b56f55';ctx.lineWidth=2;ctx.beginPath();ctx.arc(t.x,t.y,29,-Math.PI/2,-Math.PI/2+((state.time+t.phase)%4.8)/2.6*Math.PI*2);ctx.stroke();}}
// Vision is clipped by raycasting against the same walls used by detection.
const st=stats(state.bag);for(const g of room.guards){const radius=st.vision*(state.sneaking?.78:1);ctx.beginPath();ctx.moveTo(g.x,g.y);for(let i=0;i<=30;i++){const angle=g.angle-.65+i*1.3/30;let d=0;for(d=5;d<radius;d+=8){if(!sight(g,{x:g.x+Math.cos(angle)*d,y:g.y+Math.sin(angle)*d},room.walls))break;}ctx.lineTo(g.x+Math.cos(angle)*Math.min(radius,d),g.y+Math.sin(angle)*Math.min(radius,d));}ctx.closePath();ctx.fillStyle=g.alert>.1?'#d95e4740':'#e3b74735';ctx.fill();}
for(const b of room.walls){if(b.x===0||b.y===0||b.x===862||b.y===582)continue;fillRound(b.x+5,b.y+8,b.w,b.h,'#0003',3);fillRound(b.x,b.y,b.w,b.h,'#555254',3);fillRound(b.x,b.y,b.w,b.h-8,'#6a6462',3);line(b.x+3,b.y+3,b.x+b.w-3,b.y+3,'#9a8f7a',2);if(b.w>30){fillRound(b.x+7,b.y+5,b.w-14,b.h-17,'#786753',2);ctx.fillStyle='#c4a257';ctx.beginPath();ctx.arc(b.x+b.w/2,b.y+b.h/2,3,0,7);ctx.fill();}else{for(let y=b.y+35;y<b.y+b.h-10;y+=36)line(b.x,y,b.x+b.w,y,'#4c4849',2);}}
for(const l of room.loot)drawLoot(l,time);
if(st.diamond){const glow=ctx.createRadialGradient(player.x,player.y,0,player.x,player.y,45+st.diamond*4);glow.addColorStop(0,'#c8ace14a');glow.addColorStop(1,'#c8ace100');ctx.fillStyle=glow;ctx.fillRect(player.x-90,player.y-90,180,180);}
if(st.coin&&!state.sneaking&&(keys.w||keys.a||keys.s||keys.d||keys.arrowup||keys.arrowleft||keys.arrowright||keys.arrowdown||touch.up||touch.left||touch.right||touch.down)){ctx.strokeStyle='#bfa05255';ctx.lineWidth=1.5;ctx.beginPath();ctx.arc(player.x,player.y,st.noise*(.6+.4*((time*1.2)%1)),0,7);ctx.stroke();}
const actors=[...room.guards.map(g=>({...g,guard:true})),{...player,guard:false}].sort((a,b)=>a.y-b.y);for(const ac of actors){person(ac.x,ac.y,ac.guard?'#667665':'#8f72b0',ac.angle,!ac.guard,state.steps*.11);if(ac.guard&&ac.alert>.02){fillRound(ac.x-17,ac.y-41,34,5,'#423c38',2);fillRound(ac.x-17,ac.y-41,34*ac.alert,5,'#dc7255',2);text('!',ac.x,ac.y-48,18,'#bb543c');}}
if(state.sneaking)text('quiet',player.x,player.y+34,9,'#6d5b81');
if(state.mode==='playing'){const target=distance(player,e)<55?e:distance(player,a)<55?a:null;if(target){fillRound(target.x-24,target.y-59,48,23,'#292b32',5);text('E / TAP',target.x,target.y-44,8,'#fff1d2');}}
for(const p of particles){ctx.globalAlpha=p.life;ctx.fillStyle=p.color;ctx.fillRect(p.x,p.y,4,4);}ctx.globalAlpha=1;for(const f of floating)text(f.t,f.x,f.y,13,'#79623b');
// Border is rendered last for a miniature-diorama finish.
ctx.strokeStyle='#8c8270';ctx.lineWidth=2;ctx.strokeRect(37,37,826,546);for(const [x,y] of [[38,38],[842,38],[38,562],[842,562]]){fillRound(x-6,y-6,26,26,'#77706a',4);fillRound(x-3,y-3,20,16,'#918776',3);}text('↑',450,24,14,'#9d9381');if(state.detected>.01){ctx.strokeStyle=`rgba(207,91,62,${state.detected})`;ctx.lineWidth=8;ctx.strokeRect(4,4,W-8,H-8);}
}
function frame(now){const dt=Math.min(.04,(now-last)/1000||.016);last=now;const input={up:keys.w||keys.arrowup||touch.up,down:keys.s||keys.arrowdown||touch.down,left:keys.a||keys.arrowleft||touch.left,right:keys.d||keys.arrowright||touch.right,sneak:keys[' ']||touch.sneak};update(state,input,dt);
while(state.events.length){const ev=state.events.shift();if(ev.type==='pickup'){tone(ev.item.type==='diamond'?880:ev.item.type==='gold'?440:660,.12,'triangle');floating.push({x:ev.item.x,y:ev.item.y-20,t:'+'+ev.item.value,life:1});for(let i=0;i<9;i++)particles.push({x:ev.item.x,y:ev.item.y,vx:(Math.random()-.5)*80,vy:(Math.random()-.8)*90,life:1,color:LOOT[ev.item.type].color});hud();if(state.bag.length===CAPACITY)toast('Bag full! Drop loot with Q, or find your way out.');}if(ev.type==='drop')hud();if(ev.type==='caught'){state.reason=ev.reason;result(false);}}
if(state.mode==='playing'){for(const p of particles){p.x+=p.vx*dt;p.y+=p.vy*dt;p.life-=dt*1.8;}for(const f of floating){f.y-=dt*30;f.life-=dt;}particles=particles.filter(p=>p.life>0);floating=floating.filter(f=>f.life>0);const nearExit=distance(state.player,state.room.exit)<55,nearStairs=distance(state.player,state.room.stairs)<55;$('interact').innerHTML=(nearExit?'ESCAPE & BANK':nearStairs?'CLIMB HIGHER':'USE EXIT / STAIRS')+' <kbd>E</kbd>';$('hint').textContent=state.detected>.1?'You’re being spotted. Break line of sight!':nearExit?'A clean getaway. Bank your entire bag.':nearStairs?'Better loot upstairs. Feeling lucky?':state.sneaking?'Quiet footsteps. Smaller silhouette.':'Loot is automatic. Escape is a choice.';}
if(now>toastUntil)$('toast').classList.remove('show');render(state.time);requestAnimationFrame(frame);}
hud();intro();requestAnimationFrame(frame);
